    #[arg(short = 'f', long = "format", value_name = "format")]
    format: Option<Format>,

    /// Set color tint terminal output. 0 to disable, 1 to enable
    #[arg(short = 't', long = "color", value_name = "color")]
    color: Option<ColorOption>,

    /// Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f)
    #[arg(short = 'a', long = "array", value_name = "array_format")]
    array: Option<ArrayFormat>,

    /// Set function wave length
