    /// Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable
    #[arg(short = 'r', long = "prefix", value_name = "prefix")]
    prefix: Option<PrefixOption>,
}

fn parse_int_arg(name: &str, val: &str) -> Result<usize, ()> {
    val.parse::<usize>().map_err(|e| {
        eprintln!("{} expected. {}", name, e);
        eprintln!("error: invalid digit found in string");
    })
}

fn byte_to_color(byte: u8) -> u32 {
    if byte == 0 {
        22
    } else {
        byte as u32
    }
}

fn format_byte(byte: u8, fmt: &Format, use_prefix: bool) -> String {
    match fmt {
        Format::LowerHex => {
            if use_prefix {
                format!("0x{:02x}", byte)
            } else {
                format!("{:02x}", byte)
            }
        }
        Format::UpperHex => {
            if use_prefix {
                format!("0x{:02X}", byte)
            } else {
                format!("{:02X}", byte)
            }
        }
        Format::Octal => {
            if use_prefix {
                format!("0o{:04o}", byte)
            } else {
                format!("{:04o}", byte)
            }
        }
        Format::Binary => {
            if use_prefix {
                format!("0b{:08b}", byte)
            } else {
                format!("{:08b}", byte)
            }
        }
    }
}

fn byte_repr_width(fmt: &Format, use_prefix: bool) -> usize {
    match fmt {
        Format::LowerHex | Format::UpperHex => if use_prefix { 4 } else { 2 },
        Format::Octal => if use_prefix { 6 } else { 4 },
        Format::Binary => if use_prefix { 10 } else { 8 },
    }
}

fn is_printable(byte: u8) -> bool {
    byte >= 0x20 && byte <= 0x7e
}

fn output_hex(
    data: &[u8],
    cols: usize,
    fmt: &Format,
    use_prefix: bool,
    use_color: bool,
    out: &mut dyn Write,
) {
    let byte_width = byte_repr_width(fmt, use_prefix);
    let slot_width = byte_width + 1; // byte + space
    // padding slot width is always 5 (hex-width slot)
    let pad_slot_width = 5;

    let mut offset = 0usize;
    let mut i = 0usize;

    loop {
        let row_start = i;
        let row_end = (i + cols).min(data.len());
        let n_bytes = row_end - row_start;

        // Print offset
        let _ = write!(out, "0x{:06x}: ", offset);

        // Print bytes
        if use_color {
            for j in row_start..row_end {
                let byte = data[j];
                let color = byte_to_color(byte);
                let repr = format_byte(byte, fmt, use_prefix);
                let _ = write!(out, "\x1b[38;5;{}m{}\x1b[0m ", color, repr);
            }
        } else {
            for j in row_start..row_end {
                let byte = data[j];
                let repr = format_byte(byte, fmt, use_prefix);
                let _ = write!(out, "{} ", repr);
            }
        }

        // Calculate padding needed
        // Each printed byte took slot_width chars
        // Missing bytes need pad_slot_width * (cols - n_bytes) chars
        let missing = cols - n_bytes;
        let padding = missing * pad_slot_width;
        if padding > 0 {
            let _ = write!(out, "{}", " ".repeat(padding));
        }

        // Print ASCII representation
        if use_color {
            for j in row_start..row_end {
                let byte = data[j];
                let color = byte_to_color(byte);
                let ch = if is_printable(byte) { byte as char } else { '.' };
                let _ = write!(out, "\x1b[38;5;{}m{}\x1b[0m", color, ch);
            }
        } else {
            for j in row_start..row_end {
                let byte = data[j];
                let ch = if is_printable(byte) { byte as char } else { '.' };
                let _ = write!(out, "{}", ch);
            }
        }
        let _ = writeln!(out);

        offset += cols;
        i = row_end;

        if i >= data.len() {
            break;
        }
    }

    let _ = writeln!(out, "   bytes: {}", data.len());
}

fn format_byte_array(byte: u8) -> String {
    format!("0x{:02x}", byte)
}

fn output_array(data: &[u8], cols: usize, lang: &ArrayFormat, out: &mut dyn Write) {
    let n = data.len();

    // Print header
    match lang {
        ArrayFormat::Rust => {
            let _ = writeln!(out, "let ARRAY: [u8; {}] = [", n);
        }
        ArrayFormat::C => {
            let _ = writeln!(out, "unsigned char ARRAY[{}] = {{", n);
        }
        ArrayFormat::Golang => {
            let _ = writeln!(out, "a := [{}]byte{{", n);
        }
        ArrayFormat::Python => {
            let _ = writeln!(out, "a = [");
        }
        ArrayFormat::Kotlin => {
            let _ = writeln!(out, "val a = byteArrayOf(");
        }
        ArrayFormat::Java => {
            let _ = writeln!(out, "byte[] a = new byte[]{{");
        }
        ArrayFormat::Swift => {
            let _ = writeln!(out, "let a: [UInt8] = [");
        }
        ArrayFormat::FSharp => {
            let _ = writeln!(out, "let a = [|");
        }
    }

    // Process rows
    let mut i = 0;
    loop {
        let row_start = i;
        let row_end = (i + cols).min(n);
        let is_last_row = row_end >= n;
        let n_row = row_end - row_start;

        let _ = write!(out, "    ");

        match lang {
            ArrayFormat::FSharp => {
                // Uses '; ' as separator
                for j in row_start..row_end {
                    let s = format!("0x{:02x}uy", data[j]);
                    if j == row_end - 1 {
                        // last in this row
                        if is_last_row {
                            let _ = write!(out, "{}", s);
                        } else {
                            let _ = write!(out, "{}; ", s);
                        }
                    } else {
                        let _ = write!(out, "{}; ", s);
                    }
                }
            }
            ArrayFormat::Golang => {
                // Always trailing ', ' after every element
                for j in row_start..row_end {
                    let s = format_byte_array(data[j]);
                    let _ = write!(out, "{}, ", s);
                }
            }
            _ => {
                // Trailing ', ' for non-last rows, no comma on last element
                for j in row_start..row_end {
                    let s = format_byte_array(data[j]);
                    if j == row_end - 1 && is_last_row {
                        let _ = write!(out, "{}", s);
                    } else {
                        let _ = write!(out, "{}, ", s);
                    }
                }
            }
        }
        let _ = writeln!(out);

        i = row_end;

        if i >= n {
            break;
        }
    }

    // Check if we need an extra blank line
    // (when n == 0 OR n is a multiple of cols)
    if n == 0 || n % cols == 0 {
        let _ = writeln!(out, "    ");
    }

    // Print footer
    match lang {
        ArrayFormat::Rust => { let _ = writeln!(out, "];"); }
        ArrayFormat::C => { let _ = writeln!(out, "}};"); }
        ArrayFormat::Golang => { let _ = writeln!(out, "}}"); }
        ArrayFormat::Python => { let _ = writeln!(out, "]"); }
        ArrayFormat::Kotlin => { let _ = writeln!(out, ")"); }
        ArrayFormat::Java => { let _ = writeln!(out, "}};"); }
        ArrayFormat::Swift => { let _ = writeln!(out, "]"); }
        ArrayFormat::FSharp => { let _ = writeln!(out, "|]"); }
    }
}

fn output_func(n: usize, places: usize, out: &mut dyn Write) {
    let per_line = 10;
    let mut count = 0;
    for i in 0..n {
        let val = (i as f64 * PI / (2.0 * n as f64)).sin();
        let formatted = format!("{:.prec$}", val, prec = places);
        let _ = write!(out, "{},", formatted);
        count += 1;
        if count % per_line == 0 {
            let _ = writeln!(out);
        }
    }
    if count % per_line != 0 {
        let _ = writeln!(out);
    } else if count > 0 {
        let _ = writeln!(out);
    }
}

fn main() {
    let args = Args::parse();

    // Parse numeric arguments
    let cols: usize = if let Some(ref s) = args.cols {
        match parse_int_arg("-c, --cols <integer>", s) {
            Ok(v) => if v == 0 { 1 } else { v },
            Err(_) => std::process::exit(1),
        }
    } else {
        10
    };

    let len: Option<usize> = if let Some(ref s) = args.len {
        match parse_int_arg("-l, --len <integer>", s) {
            Ok(v) => Some(v),
            Err(_) => std::process::exit(1),
        }
    } else {
        None
    };

    let func_len: Option<usize> = if let Some(ref s) = args.func {
        match parse_int_arg("-u, --func <integer>", s) {
            Ok(v) => Some(v),
            Err(_) => std::process::exit(1),
        }
    } else {
        None
    };

    let places: usize = if let Some(ref s) = args.places {
        // If invalid, just use default (4)
        s.parse::<usize>().unwrap_or(4)
    } else {
        4
    };

    // Handle func mode
    if let Some(n) = func_len {
        let stdout = io::stdout();
        let mut out = stdout.lock();
        output_func(n, places, &mut out);
        return;
    }

    // Determine color setting
    let stdout = io::stdout();
    let is_tty = stdout.is_terminal();
    let no_color = std::env::var("NO_COLOR").is_ok();

    let use_color = match args.color {
        Some(ColorOption::Off) => false,
        Some(ColorOption::On) => true,
        None => {
            if no_color {
                false
            } else {
                is_tty
            }
        }
    };

    let fmt = args.format.unwrap_or(Format::LowerHex);
    let use_prefix = match args.prefix {
        Some(PrefixOption::Off) => false,
        Some(PrefixOption::On) => true,
        None => true,
    };

    // Read input
    let data: Vec<u8> = if let Some(ref path) = args.inputfile {
        let mut file = match File::open(Path::new(path)) {
            Ok(f) => f,
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        };
        let mut buf = Vec::new();
        match file.read_to_end(&mut buf) {
            Ok(_) => {}
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
        buf
    } else {
        let mut buf = Vec::new();
        match io::stdin().read_to_end(&mut buf) {
            Ok(_) => {}
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
        buf
    };

    // Apply len limit
    let data = if let Some(l) = len {
        &data[..l.min(data.len())]
    } else {
        &data[..]
    };

    let mut out_writer = io::stdout();

    if let Some(ref lang) = args.array {
        output_array(data, cols, lang, &mut out_writer);
    } else {
        output_hex(data, cols, &fmt, use_prefix, use_color, &mut out_writer);
    }
}
