                let _ = write!(out, "\x1b[38;5;{}m{}\x1b[0m", color, ch);
            }
        } else {
            for j in row_start..row_end {
                let byte = data[j];
                let ch = if is_printable(byte) { byte as char } else { '.' };
                let _ = write!(out, "{}", ch);
            }
        }
        let _ = writeln!(out);

        offset += cols;
        i = row_end;

        if i >= data.len() {
            break;
        }
    }

    let _ = writeln!(out, "   bytes: {}", data.len());
}

fn format_byte_array(byte: u8) -> String {
    format!("0x{:02x}", byte)
}

fn output_array(data: &[u8], cols: usize, lang: &ArrayFormat, out: &mut dyn Write) {
    let n = data.len();

    // Print header
    match lang {
        ArrayFormat::Rust => {
            let _ = writeln!(out, "let ARRAY: [u8; {}] = [", n);
        }
        ArrayFormat::C => {
            let _ = writeln!(out, "unsigned char ARRAY[{}] = {{", n);
        }
        ArrayFormat::Golang => {
            let _ = writeln!(out, "a := [{}]byte{{", n);
        }
        ArrayFormat::Python => {
            let _ = writeln!(out, "a = [");
        }
        ArrayFormat::Kotlin => {
            let _ = writeln!(out, "val a = byteArrayOf(");
        }
        ArrayFormat::Java => {
            let _ = writeln!(out, "byte[] a = new byte[]{{");
        }
        ArrayFormat::Swift => {
            let _ = writeln!(out, "let a: [UInt8] = [");
        }
        ArrayFormat::FSharp => {
            let _ = writeln!(out, "let a = [|");
        }
    }

    // Process rows
    let mut i = 0;
    loop {
        let row_start = i;
        let row_end = (i + cols).min(n);
        let is_last_row = row_end >= n;
        let n_row = row_end - row_start;

        let _ = write!(out, "    ");

        match lang {
            ArrayFormat::FSharp => {
                // Uses '; ' as separator
                for j in row_start..row_end {
                    let s = format!("0x{:02x}uy", data[j]);
                    if j == row_end - 1 {
                        // last in this row
                        if is_last_row {
                            let _ = write!(out, "{}", s);
                        } else {
                            let _ = write!(out, "{}; ", s);
                        }
                    } else {
                        let _ = write!(out, "{}; ", s);
                    }
                }
            }
            ArrayFormat::Golang => {
                // Always trailing ', ' after every element
                for j in row_start..row_end {
                    let s = format_byte_array(data[j]);
                    let _ = write!(out, "{}, ", s);
                }
            }
            _ => {
                // Trailing ', ' for non-last rows, no comma on last element
                for j in row_start..row_end {
                    let s = format_byte_array(data[j]);
                    if j == row_end - 1 && is_last_row {
                        let _ = write!(out, "{}", s);
                    } else {
                        let _ = write!(out, "{}, ", s);
                    }
                }
            }
        }
        let _ = writeln!(out);

        i = row_end;

        if i >= n {
            break;
        }
    }

    // Check if we need an extra blank line
    // (when n == 0 OR n is a multiple of cols)
    if n == 0 || n % cols == 0 {
        let _ = writeln!(out, "    ");
    }

    // Print footer
    match lang {
        ArrayFormat::Rust => { let _ = writeln!(out, "];"); }
        ArrayFormat::C => { let _ = writeln!(out, "}};"); }
        ArrayFormat::Golang => { let _ = writeln!(out, "}}"); }
        ArrayFormat::Python => { let _ = writeln!(out, "]"); }
        ArrayFormat::Kotlin => { let _ = writeln!(out, ")"); }
        ArrayFormat::Java => { let _ = writeln!(out, "}};"); }
        ArrayFormat::Swift => { let _ = writeln!(out, "]"); }
        ArrayFormat::FSharp => { let _ = writeln!(out, "|]"); }
    }
}

fn output_func(n: usize, places: usize, out: &mut dyn Write) {
    let per_line = 10;
    let mut count = 0;
    for i in 0..n {
        let val = (i as f64 * PI / (2.0 * n as f64)).sin();
        let formatted = format!("{:.prec$}", val, prec = places);
        let _ = write!(out, "{},", formatted);
        count += 1;
        if count % per_line == 0 {
            let _ = writeln!(out);
        }
    }
    if count % per_line != 0 {
        let _ = writeln!(out);
    } else if count > 0 {
        let _ = writeln!(out);
    }
}

