        }
    }
}

fn byte_repr_width(fmt: &Format, use_prefix: bool) -> usize {
    match fmt {
        Format::LowerHex | Format::UpperHex => if use_prefix { 4 } else { 2 },
        Format::Octal => if use_prefix { 6 } else { 4 },
        Format::Binary => if use_prefix { 10 } else { 8 },
    }
}

fn is_printable(byte: u8) -> bool {
    byte >= 0x20 && byte <= 0x7e
}

fn output_hex(
    data: &[u8],
    cols: usize,
    fmt: &Format,
    use_prefix: bool,
    use_color: bool,
    out: &mut dyn Write,
) {
    let _byte_width = byte_repr_width(fmt, use_prefix);
    // padding slot width is always 5 (hex-equivalent width)
    let pad_slot_width: usize = 5;

    let mut offset = 0usize;
    let mut i = 0usize;

    loop {
        let row_start = i;
        let row_end = (i + cols).min(data.len());
        let n_bytes = row_end - row_start;

        // Print offset
        let _ = write!(out, "0x{:06x}: ", offset);

        // Print bytes
        if use_color {
            for j in row_start..row_end {
                let byte = data[j];
                let color = byte_to_color(byte);
                let repr = format_byte(byte, fmt, use_prefix);
