                }
            }
            ArrayLang::Golang => {
                for j in row_start..row_end {
                    let s = format!("0x{:02x}", data[j]);
                    let _ = write!(out, "{}, ", s);
                }
            }
            _ => {
                for j in row_start..row_end {
                    let s = format!("0x{:02x}", data[j]);
                    if j == row_end - 1 && is_last_row {
                        let _ = write!(out, "{}", s);
                    } else {
                        let _ = write!(out, "{}, ", s);
                    }
                }
            }
        }
        let _ = writeln!(out);

        i = row_end;
        if i >= n {
            break;
        }
    }

    // Extra blank line when n == 0 or n is a multiple of cols
    if n == 0 || n % cols == 0 {
        let _ = writeln!(out, "    ");
    }

