        let _ = write!(out, "{},", formatted);
        count += 1;
        if count % per_line == 0 {
            let _ = writeln!(out);
        }
    }
    if count % per_line != 0 {
        let _ = writeln!(out);
    } else if count > 0 {
        let _ = writeln!(out);
