        let _ = write!(out, "0x{:06x}: ", offset);

        // Print bytes
        if use_color {
            for j in row_start..row_end {
                let byte = data[j];
                let color = byte_to_color(byte);
                let repr = format_byte(byte, fmt, use_prefix);
                let _ = write!(out, "\x1b[38;5;{}m{}\x1b[0m ", color, repr);
            }
        } else {
            for j in row_start..row_end {
                let byte = data[j];
                let repr = format_byte(byte, fmt, use_prefix);
                let _ = write!(out, "{} ", repr);
            }
