    LowerHex,
    UpperHex,
    Binary,
}

#[derive(Debug, Clone, PartialEq)]
enum ArrayLang {
    Rust,
    C,
    Golang,
    Python,
    Kotlin,
    Java,
    Swift,
    FSharp,
}

fn byte_to_color(byte: u8) -> u32 {
    if byte == 0 { 22 } else { byte as u32 }
}

fn format_byte(byte: u8, fmt: &Format, use_prefix: bool) -> String {
    match fmt {
        Format::LowerHex => {
            if use_prefix { format!("0x{:02x}", byte) } else { format!("{:02x}", byte) }
        }
        Format::UpperHex => {
            if use_prefix { format!("0x{:02X}", byte) } else { format!("{:02X}", byte) }
        }
        Format::Octal => {
            if use_prefix { format!("0o{:04o}", byte) } else { format!("{:04o}", byte) }
        }
        Format::Binary => {
            if use_prefix { format!("0b{:08b}", byte) } else { format!("{:08b}", byte) }
        }
    }
}

fn is_printable(byte: u8) -> bool {
    byte >= 0x20 && byte <= 0x7e
}

fn output_hex(
    data: &[u8],
    cols: usize,  // original cols value (may be 0)
    fmt: &Format,
    use_prefix: bool,
    use_color: bool,
    out: &mut dyn Write,
) {
    let n = data.len();
    // Effective chunk size: at least 1
    let eff_cols = if cols == 0 { 1 } else { cols };

    // Number of rows to print (including potential trailing empty row)
    let num_rows = if n == 0 {
        1
    } else if n % eff_cols == 0 {
        n / eff_cols + 1
    } else {
        (n + eff_cols - 1) / eff_cols
    };

    for row_idx in 0..num_rows {
        let offset = row_idx * eff_cols;
        let row_start = offset.min(n);
        let row_end = (offset + eff_cols).min(n);
        let n_bytes = row_end - row_start;

        // Print offset
        let _ = write!(out, "0x{:06x}: ", offset);

        // Print bytes
        if use_color {
            for j in row_start..row_end {
                let byte = data[j];
                let color = byte_to_color(byte);
                let repr = format_byte(byte, fmt, use_prefix);
                let _ = write!(out, "\x1b[38;5;{}m{}\x1b[0m ", color, repr);
            }
        } else {
            for j in row_start..row_end {
                let byte = data[j];
                let repr = format_byte(byte, fmt, use_prefix);
                let _ = write!(out, "{} ", repr);
            }
        }

        // Padding for missing bytes (always 5 chars per slot, based on eff_cols)
        // But for the trailing empty row when original cols==0: eff_cols=1, n_bytes=0
        // missing = eff_cols - n_bytes = 1 - 0 = 1, but cols=0 so we want 0 padding
        // So: if this is the trailing empty row and cols==0, use 0 padding
        let missing = if cols == 0 && n_bytes == 0 {
            0
        } else {
            eff_cols - n_bytes
        };
        let padding = missing * 5;
        if padding > 0 {
            let _ = write!(out, "{}", " ".repeat(padding));
        }

        // Print ASCII representation
        if use_color {
            for j in row_start..row_end {
                let byte = data[j];
                let color = byte_to_color(byte);
                let ch = if is_printable(byte) { byte as char } else { '.' };
                let _ = write!(out, "\x1b[38;5;{}m{}\x1b[0m", color, ch);
            }
        } else {
            for j in row_start..row_end {
                let byte = data[j];
                let ch = if is_printable(byte) { byte as char } else { '.' };
                let _ = write!(out, "{}", ch);
            }
        }
        let _ = writeln!(out);
    }

    let _ = writeln!(out, "   bytes: {}", n);
}

fn output_array(data: &[u8], cols: usize, lang: &ArrayLang, out: &mut dyn Write) {
    let n = data.len();
    let eff_cols = if cols == 0 { 1 } else { cols };

    // Print header
    match lang {
        ArrayLang::Rust => { let _ = writeln!(out, "let ARRAY: [u8; {}] = [", n); }
        ArrayLang::C => { let _ = writeln!(out, "unsigned char ARRAY[{}] = {{", n); }
        ArrayLang::Golang => { let _ = writeln!(out, "a := [{}]byte{{", n); }
        ArrayLang::Python => { let _ = writeln!(out, "a = ["); }
        ArrayLang::Kotlin => { let _ = writeln!(out, "val a = byteArrayOf("); }
        ArrayLang::Java => { let _ = writeln!(out, "byte[] a = new byte[]{{"); }
        ArrayLang::Swift => { let _ = writeln!(out, "let a: [UInt8] = ["); }
        ArrayLang::FSharp => { let _ = writeln!(out, "let a = [|"); }
    }

    // Process rows
    let mut i = 0;
    loop {
        let row_start = i;
        let row_end = (i + eff_cols).min(n);
        let is_last_row = row_end >= n;

        let _ = write!(out, "    ");

        match lang {
            ArrayLang::FSharp => {
                for j in row_start..row_end {
                    let s = format!("0x{:02x}uy", data[j]);
                    if j == row_end - 1 && is_last_row {
                        let _ = write!(out, "{}", s);
                    } else {
                        let _ = write!(out, "{}; ", s);
                    }
                }
            }
            ArrayLang::Golang => {
                for j in row_start..row_end {
                    let s = format!("0x{:02x}", data[j]);
                    let _ = write!(out, "{}, ", s);
                }
            }
            _ => {
                for j in row_start..row_end {
                    let s = format!("0x{:02x}", data[j]);
                    if j == row_end - 1 && is_last_row {
                        let _ = write!(out, "{}", s);
                    } else {
                        let _ = write!(out, "{}, ", s);
                    }
                }
            }
        }
        let _ = writeln!(out);

        i = row_end;
        if i >= n {
            break;
        }
    }

    // Extra blank line when n == 0 or n is a multiple of eff_cols
    if n == 0 || n % eff_cols == 0 {
        let _ = writeln!(out, "    ");
    }

    // Print footer
    match lang {
        ArrayLang::Rust => { let _ = writeln!(out, "];"); }
        ArrayLang::C => { let _ = writeln!(out, "}};"); }
        ArrayLang::Golang => { let _ = writeln!(out, "}}"); }
        ArrayLang::Python => { let _ = writeln!(out, "]"); }
        ArrayLang::Kotlin => { let _ = writeln!(out, ")"); }
        ArrayLang::Java => { let _ = writeln!(out, "}};"); }
        ArrayLang::Swift => { let _ = writeln!(out, "]"); }
        ArrayLang::FSharp => { let _ = writeln!(out, "|]"); }
    }
}

fn output_func(n: usize, places: usize, out: &mut dyn Write) {
    let per_line = 10usize;
    let mut count = 0usize;
    for i in 0..n {
        let val = (i as f64 * PI / (2.0 * n as f64)).sin();
        let formatted = format!("{:.prec$}", val, prec = places);
        let _ = write!(out, "{},", formatted);
        count += 1;
        if count % per_line == 0 {
            let _ = writeln!(out);
        }
    }
    if count % per_line != 0 {
        let _ = writeln!(out);
    } else if count > 0 {
        let _ = writeln!(out);
    }
}

fn print_usage() {
    println!("Futuristic take on hexdump, made in Rust.");
    println!();
    println!("Usage: hx [OPTIONS] [INPUTFILE]");
    println!();
    println!("Arguments:");
    println!("  [INPUTFILE]  Pass file path as an argument, or input data may be passed via stdin");
    println!();
    println!("Options:");
    println!("  -c, --cols <columns>        Set column length");
    println!("  -l, --len <len>             Set <len> bytes to read");
    println!("  -f, --format <format>       Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b) [possible values: o, x, X, b]");
    println!("  -t, --color <color>         Set color tint terminal output. 0 to disable, 1 to enable [possible values: 0, 1]");
    println!("  -a, --array <array_format>  Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f) [possible values: r, c, g, p, k, j, s, f]");
    println!("  -u, --func <func_length>    Set function wave length");
    println!("  -p, --places <func_places>  Set function wave output decimal places");
    println!("  -r, --prefix <prefix>       Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable [possible values: 0, 1]");
    println!("  -h, --help                  Print help");
    println!("  -V, --version               Print version");
}

fn main() {
    let raw_args: Vec<String> = std::env::args().collect();

    let mut cols_str: Option<String> = None;
    let mut len_str: Option<String> = None;
    let mut fmt_opt: Option<Format> = None;
    let mut color_opt: Option<bool> = None;
    let mut array_opt: Option<ArrayLang> = None;
    let mut func_str: Option<String> = None;
    let mut places_str: Option<String> = None;
    let mut prefix_opt: Option<bool> = None;
    let mut inputfile: Option<String> = None;

    let mut idx = 1;
    while idx < raw_args.len() {
        let arg = &raw_args[idx];
        match arg.as_str() {
            "-h" | "--help" => {
                print_usage();
                return;
            }
            "-V" | "--version" => {
                println!("hx 0.7.0");
                return;
            }
            "-c" | "--cols" => {
                idx += 1;
                if idx < raw_args.len() {
                    cols_str = Some(raw_args[idx].clone());
                }
            }
            "-l" | "--len" => {
                idx += 1;
                if idx < raw_args.len() {
                    len_str = Some(raw_args[idx].clone());
                }
            }
            "-f" | "--format" => {
                idx += 1;
                if idx < raw_args.len() {
                    let v = &raw_args[idx];
                    fmt_opt = match v.as_str() {
                        "o" => Some(Format::Octal),
                        "x" => Some(Format::LowerHex),
                        "X" => Some(Format::UpperHex),
                        "b" => Some(Format::Binary),
                        _ => {
                            eprintln!("error: invalid value '{}' for '--format <format>'", v);
                            eprintln!("  [possible values: o, x, X, b]");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                    };
                }
            }
            "-t" | "--color" => {
                idx += 1;
                if idx < raw_args.len() {
                    let v = &raw_args[idx];
                    color_opt = match v.as_str() {
                        "0" => Some(false),
                        "1" => Some(true),
                        _ => {
                            eprintln!("error: invalid value '{}' for '--color <color>'", v);
                            eprintln!("  [possible values: 0, 1]");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                    };
                }
            }
            "-a" | "--array" => {
                idx += 1;
                if idx < raw_args.len() {
                    let v = &raw_args[idx];
                    array_opt = match v.as_str() {
                        "r" => Some(ArrayLang::Rust),
                        "c" => Some(ArrayLang::C),
                        "g" => Some(ArrayLang::Golang),
                        "p" => Some(ArrayLang::Python),
                        "k" => Some(ArrayLang::Kotlin),
                        "j" => Some(ArrayLang::Java),
                        "s" => Some(ArrayLang::Swift),
                        "f" => Some(ArrayLang::FSharp),
                        _ => {
                            eprintln!("error: invalid value '{}' for '--array <array_format>'", v);
                            eprintln!("  [possible values: r, c, g, p, k, j, s, f]");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                    };
                }
            }
            "-u" | "--func" => {
                idx += 1;
                if idx < raw_args.len() {
                    func_str = Some(raw_args[idx].clone());
                }
            }
            "-p" | "--places" => {
                idx += 1;
                if idx < raw_args.len() {
                    places_str = Some(raw_args[idx].clone());
                }
            }
            "-r" | "--prefix" => {
                idx += 1;
                if idx < raw_args.len() {
                    let v = &raw_args[idx];
                    prefix_opt = match v.as_str() {
                        "0" => Some(false),
                        "1" => Some(true),
                        _ => {
                            eprintln!("error: invalid value '{}' for '--prefix <prefix>'", v);
                            eprintln!("  [possible values: 0, 1]");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                    };
                }
            }
            _ => {
                if arg.starts_with('-') {
                    eprintln!("error: unexpected argument '{}' found", arg);
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                } else {
                    inputfile = Some(arg.clone());
                }
            }
        }
        idx += 1;
    }

    // Parse integer arguments
    let parse_usize_arg = |name: &str, val: &str| -> Option<usize> {
        match val.parse::<usize>() {
            Ok(v) => Some(v),
            Err(e) => {
                eprintln!("{} expected. {}", name, e);
                eprintln!("error: invalid digit found in string");
                None
            }
        }
    };

    // cols: keep the original value (including 0)
    let cols_val: usize = if let Some(ref s) = cols_str {
        match parse_usize_arg("-c, --cols <integer>", s) {
            Some(v) => v,  // Keep 0 as 0
            None => std::process::exit(1),
        }
    } else {
        10
    };

    let len_val: Option<usize> = if let Some(ref s) = len_str {
        match parse_usize_arg("-l, --len <integer>", s) {
            Some(v) => Some(v),
            None => std::process::exit(1),
        }
    } else {
        None
    };

    let func_val: Option<usize> = if let Some(ref s) = func_str {
        match parse_usize_arg("-u, --func <integer>", s) {
            Some(v) => Some(v),
            None => std::process::exit(1),
        }
    } else {
        None
    };

    let places_val: usize = if let Some(ref s) = places_str {
        s.parse::<usize>().unwrap_or(4)
    } else {
        4
    };

    // Handle func mode
    if let Some(n) = func_val {
        let stdout = io::stdout();
        let mut out = stdout.lock();
        output_func(n, places_val, &mut out);
        return;
    }

    // Determine color setting
    let stdout_check = io::stdout();
    let is_tty = stdout_check.is_terminal();
    let no_color = std::env::var("NO_COLOR").is_ok();

    let use_color = match color_opt {
        Some(v) => v,
        None => {
            if no_color { false } else { is_tty }
        }
    };

    let fmt = fmt_opt.unwrap_or(Format::LowerHex);
    let use_prefix = prefix_opt.unwrap_or(true);

    // Read input
    let data: Vec<u8> = if let Some(ref path) = inputfile {
        let mut file = match File::open(Path::new(path)) {
            Ok(f) => f,
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        };
        let mut buf = Vec::new();
        match file.read_to_end(&mut buf) {
            Ok(_) => {}
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
        buf
    } else {
        let mut buf = Vec::new();
        match io::stdin().read_to_end(&mut buf) {
            Ok(_) => {}
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
        buf
    };

    // Apply len limit
    let data_slice = if let Some(l) = len_val {
        &data[..l.min(data.len())]
    } else {
        &data[..]
    };

    let mut out_writer = io::stdout();

    if let Some(ref lang) = array_opt {
        output_array(data_slice, cols_val, lang, &mut out_writer);
    } else {
        output_hex(data_slice, cols_val, &fmt, use_prefix, use_color, &mut out_writer);
    }
}
